                   else ("petition_cash_out", "cash_exhausted"))
        occasion, kw = (f"floor{ctx}", {"k": s.k + 1}) if node == "cash_floor" else ("cash_out", {"out": "done"})

        def go(y: _S, b: str) -> None:
